<?php
/** Quetta Workbench facility records: storage providers manage only their own capacity and compatible produce through protected PHP forms. */
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/workspace.php';
require_once __DIR__ . '/../includes/storage-facility-management.php';

$user = require_role(['storage_provider']);
$errors = [];
$submittedValues = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    [$success, $message, $meta] = save_storage_facility((int) $user['id'], $_POST);
    if ($success) {
        flash('success', $message);
        redirect('storage/facilities.php' . (!empty($meta['facility_id']) ? '?edit=' . (int) $meta['facility_id'] : ''));
    }
    $errors = $meta['errors'] ?? [];
    $submittedValues = $meta['values'] ?? [];
    flash('error', $message);
}
$provider = storage_provider_profile_for_user((int) $user['id']);
$providerId = (int) ($provider['id'] ?? 0);
$editId = filter_input(INPUT_GET, 'edit', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0;
$editing = $editId > 0 && $providerId > 0 ? storage_facility_for_provider($providerId, $editId) : null;
$categories = storage_facility_category_catalog();
$locations = role_profile_locations();
$form = $submittedValues + ($editing ?? ['name' => '', 'description' => '', 'location_id' => 0, 'storage_type' => 'cold_storage', 'total_capacity_kg' => '', 'price_per_kg_day' => '', 'status' => 'draft', 'category_ids' => []]);
$facilities = $providerId > 0 ? storage_facilities_for_provider($providerId) : [];
$locationLabel = static fn (array $location): string => implode(' · ', array_filter([$location['district'] ?? '', $location['tehsil'] ?? '', $location['area'] ?? '']));
workspace_open('Facility records', 'facilities');
?>
<section class="workspace-section facility-editor"><div class="workspace-section-header"><div><h2><?= $editing ? 'Edit facility' : 'Add a facility' ?></h2><p>Keep capacity, service type, daily price, and compatible produce current. Active capacity becomes available in the storage marketplace.</p></div></div><?php if ($message = flash('success')): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if ($message = flash('error')): ?><div class="alert alert-error"><?= e($message) ?></div><?php endif; ?><form method="post" class="form-grid profile-form" novalidate><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><?php if ($editing): ?><input type="hidden" name="facility_id" value="<?= (int) $editing['id'] ?>"><?php endif; ?><div class="form-field"><label for="facility_name">Facility name</label><input id="facility_name" name="facility_name" maxlength="160" required value="<?= e((string) ($form['name'] ?? '')) ?>"><?php if (isset($errors['facility_name'])): ?><small class="field-error"><?= e($errors['facility_name']) ?></small><?php endif; ?></div><div class="form-field"><label for="location_id">Facility location</label><select id="location_id" name="location_id" required><option value="">Choose a location</option><?php foreach ($locations as $location): ?><option value="<?= (int) $location['id'] ?>" <?= (int) ($form['location_id'] ?? 0) === (int) $location['id'] ? 'selected' : '' ?>><?= e($locationLabel($location)) ?></option><?php endforeach; ?></select><?php if (isset($errors['location_id'])): ?><small class="field-error"><?= e($errors['location_id']) ?></small><?php endif; ?></div><div class="form-field"><label for="storage_type">Storage type</label><select id="storage_type" name="storage_type" required><?php foreach (storage_facility_type_options() as $value => $label): ?><option value="<?= e($value) ?>" <?= ($form['storage_type'] ?? '') === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><?php if (isset($errors['storage_type'])): ?><small class="field-error"><?= e($errors['storage_type']) ?></small><?php endif; ?></div><div class="form-field"><label for="status">Marketplace status</label><select id="status" name="status" required><?php foreach (storage_facility_status_options() as $value => $label): ?><option value="<?= e($value) ?>" <?= ($form['status'] ?? '') === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><?php if (isset($errors['status'])): ?><small class="field-error"><?= e($errors['status']) ?></small><?php endif; ?></div><div class="form-field"><label for="total_capacity_kg">Total capacity (kg)</label><input id="total_capacity_kg" name="total_capacity_kg" type="number" min="0.01" max="100000000" step="0.01" required value="<?= e((string) ($form['total_capacity_kg'] ?? '')) ?>"><?php if (isset($errors['total_capacity_kg'])): ?><small class="field-error"><?= e($errors['total_capacity_kg']) ?></small><?php endif; ?></div><div class="form-field"><label for="price_per_kg_day">Daily price (Rs./kg)</label><input id="price_per_kg_day" name="price_per_kg_day" type="number" min="0.0001" max="1000000" step="0.0001" required value="<?= e((string) ($form['price_per_kg_day'] ?? '')) ?>"><?php if (isset($errors['price_per_kg_day'])): ?><small class="field-error"><?= e($errors['price_per_kg_day']) ?></small><?php endif; ?></div><div class="form-field facility-description"><label for="facility_description">Facility details</label><textarea id="facility_description" name="facility_description" maxlength="1000" rows="4" placeholder="Temperature handling, access, or booking information farmers should know."><?= e((string) ($form['description'] ?? '')) ?></textarea></div><fieldset class="supported-produce"><legend>Supported produce</legend><p>Choose every active crop category this facility can safely store.</p><div class="supported-produce-grid"><?php foreach ($categories as $category): ?><label><input type="checkbox" name="category_ids[]" value="<?= (int) $category['id'] ?>" <?= in_array((int) $category['id'], array_map('intval', $form['category_ids'] ?? []), true) ? 'checked' : '' ?>> <span><?= e($category['name']) ?></span></label><?php endforeach; ?></div><?php if (isset($errors['category_ids'])): ?><small class="field-error"><?= e($errors['category_ids']) ?></small><?php endif; ?></fieldset><div class="form-actions"><?php if ($editing): ?><a class="button button-outline" href="<?= e(app_url('storage/facilities.php')) ?>">Cancel edit</a><?php endif; ?><button class="button button-primary" type="submit"><?= $editing ? 'Save facility' : 'Add facility' ?></button></div></form></section>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Your facility records</h2><p>Only facilities owned by this storage-provider account appear here. Capacity already reserved by approved or active bookings remains protected when you edit total capacity.</p></div><span class="status-pill"><?= count($facilities) ?> recorded</span></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Facility</th><th>Location</th><th>Capacity</th><th>Daily price</th><th>Supported produce</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if ($facilities === []): ?><tr><td colspan="7">No facility records yet. Add verified capacity when your storage operation is ready.</td></tr><?php else: foreach ($facilities as $facility): ?><tr><td><strong><?= e($facility['name']) ?></strong><br><span class="muted"><?= e(ucwords(str_replace('_', ' ', $facility['storage_type']))) ?></span></td><td><?= e(implode(', ', array_filter([$facility['district'], $facility['tehsil']]))) ?></td><td><?= number_format((float) $facility['available_capacity_kg'], 0) ?> available<br><span class="muted"><?= number_format((float) $facility['total_capacity_kg'], 0) ?> total kg</span></td><td>Rs. <?= number_format((float) $facility['price_per_kg_day'], 2) ?>/kg</td><td><?= e($facility['supported_products'] ?: 'No categories recorded') ?></td><td><span class="status-pill <?= e($facility['status']) ?>"><?= e(ucfirst($facility['status'])) ?></span></td><td><a class="button button-quiet" href="<?= e(app_url('storage/facilities.php?edit=' . (int) $facility['id'])) ?>">Edit</a></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<?php workspace_close(); ?>
